        for attr, obj in vars(mod).items():
            if inspect.isclass(obj) and issubclass(obj, BaseException) and obj.__module__ == mod.__name__:
                key = (f.replace(SRC + '/', ''), obj.__name__)
                cov = issubclass(obj, declared)
                seen.setdefault(key, set()).add(cov)
    for k, v in sorted(seen.items()):
        if v != {True}:
            uncovered.append({'file': k[0], 'class': k[1], 'coveredInSomeLoad': True in v})
    res['COVER'] = {'exceptionClassesDefinedInLoadedSourceModules': len(seen), 'notCoveredByReplayStackDeclarations': uncovered[:60]}
