"""Independent reviewer probe (static, reads source only; writes only this runtime's receipts).

Question: identity-model.v3 open_run_closure calls owning-unit functions (native, workflow) WITHOUT a local
try/except at several call sites. close_run then normalizes only the replay stack's declared class objects.
Which raise statements are statically reachable from those unwrapped entry points, and are they AdmissionError
family raises (owner refusals that would escape normalization) or other exceptions?

Approximation limits: intra-module call graph by bare Name / module-attribute-free calls only; a raise enclosed by
any try in the same function whose handler names the raised class, AdmissionError, NativeRefusal/ScopeRefusal base,
Exception or a bare except is treated as caught; dynamic dispatch, getattr and cross-module calls are not followed.
Reachability here is syntactic, not a demonstration that retained bytes reach the site.
"""
import ast
import json
import sys
from pathlib import Path

RT = Path('/private/tmp/opensip-design-corrections/claude-independent-design.v38')
SRC = RT / 'work/source38-pkg/docs/coop/design-corrections'
OUT = RT / 'receipts/static-raise-reachability.json'

TARGETS = {
    'native/native_evidence_model.v2.py': {
        'unwrappedEntries': ['syntax_capability_support', 'source_variant_capability_support', 'clone_ownership_disclosure',
                             'admit_native_context', 'admit_capability_manifest', '_rung_index', 'admit_coverage_result_v3',
                             'bind_typescript_universe', 'bind_rust_universe', 'bind_syntax_universe'],
        'wrappedEntries': ['admit_requested_capabilities'],
        'admissionFamily': {'AdmissionError', 'NativeRefusal', 'ScopeRefusal', 'C.AdmissionError'},
    },
    'workflows/workflows_model.v3.py': {
        'unwrappedEntries': ['registry_row', 'rule_program_digest'],
        'wrappedEntries': ['validate_import_record'],
        'admissionFamily': {'Refusal', 'AdmissionError', 'C.AdmissionError'},
    },
}


def dotted(node):
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = dotted(node.value)
        return base + '.' + node.attr if base else node.attr
    if isinstance(node, ast.Call):
        return dotted(node.func)
    return None


class FunctionFacts(ast.NodeVisitor):
    def __init__(self):
        self.calls, self.raises, self.try_stack = set(), [], []

    def visit_Try(self, node):
        caught = set()
        for h in node.handlers:
            if h.type is None:
                caught.add('*')
            elif isinstance(h.type, ast.Tuple):
                caught.update(filter(None, (dotted(e) for e in h.type.elts)))
            else:
                caught.add(dotted(h.type))
        self.try_stack.append(caught)
        for stmt in node.body:
            self.visit(stmt)
        self.try_stack.pop()
        for part in node.handlers + node.orelse + node.finalbody:
            self.visit(part)

    visit_TryStar = visit_Try

    def visit_Call(self, node):
        name = dotted(node.func)
        if name and '.' not in name:
            self.calls.add(name)
        self.generic_visit(node)

    def visit_Raise(self, node):
        name = dotted(node.exc) if node.exc is not None else '<reraise>'
        enclosing = set().union(*self.try_stack) if self.try_stack else set()
        self.raises.append({'line': node.lineno, 'exception': name, 'enclosingHandlers': sorted(x for x in enclosing if x)})
        self.generic_visit(node)

    def visit_FunctionDef(self, node):
        # nested defs are analysed as part of the enclosing function (conservative)
        for stmt in node.body:
            self.visit(stmt)

    visit_AsyncFunctionDef = visit_FunctionDef


def analyse(rel, spec):
    tree = ast.parse((SRC / rel).read_text(encoding='utf-8'))
    functions = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            facts = FunctionFacts()
            for stmt in node.body:
                facts.visit(stmt)
            functions[node.name] = facts
    classes = {n.name: [dotted(b) for b in n.bases] for n in tree.body if isinstance(n, ast.ClassDef)}

    def family(exc):
        seen, todo = set(), [exc.split('(')[0]]
        while todo:
            c = todo.pop()
            if c in seen:
                continue
            seen.add(c)
            if c in spec['admissionFamily']:
                return True
            todo.extend(b for b in classes.get(c, []) if b)
        return False

    def caught(raise_row):
        h = set(raise_row['enclosingHandlers'])
        exc = raise_row['exception']
        return bool(h & {'*', 'Exception', 'BaseException', exc} | (h & spec['admissionFamily'] if family(exc) else set()))

    result = {}
    for entry in spec['unwrappedEntries'] + spec['wrappedEntries']:
        if entry not in functions:
            result[entry] = {'error': 'not a top-level function'}
            continue
        reach, todo = set(), [entry]
        while todo:
            f = todo.pop()
            if f in reach or f not in functions:
                continue
            reach.add(f)
            todo.extend(functions[f].calls)
        escaping = []
        for f in sorted(reach):
            for r in functions[f].raises:
                if not caught(r):
                    escaping.append(dict(r, function=f, admissionFamily=family(r['exception'])))
        result[entry] = {
            'wrappedAtIdentityCallSite': entry in spec['wrappedEntries'],
            'reachableFunctions': len(reach),
            'uncaughtRaiseSites': len(escaping),
            'uncaughtAdmissionFamilyRaiseSites': sum(1 for r in escaping if r['admissionFamily']),
            'admissionFamilyExceptions': sorted({r['exception'] for r in escaping if r['admissionFamily']}),
            'otherExceptions': sorted({r['exception'] for r in escaping if not r['admissionFamily']}),
            'admissionFamilySamples': [r for r in escaping if r['admissionFamily']][:12],
        }
    return result


out = {'standing': 'independent reviewer static probe; syntactic reachability only, not a retained-bytes demonstration',
       'python': sys.version.split()[0], 'results': {rel: analyse(rel, spec) for rel, spec in TARGETS.items()}}
OUT.write_text(json.dumps(out, indent=1, sort_keys=True) + '\n')
for rel, rows in out['results'].items():
