        print(rel, entry, {k: row.get(k) for k in ('wrappedAtIdentityCallSite', 'reachableFunctions', 'uncaughtRaiseSites',
                                                   'uncaughtAdmissionFamilyRaiseSites', 'admissionFamilyExceptions', 'otherExceptions', 'error')})

