def leaf_counts(node, out):
    if isinstance(node, str):
        for tag in ('ADMIT', 'REFUSE', 'HARNESS'):
            if node.startswith(tag):
                out[tag] = out.get(tag, 0) + 1
    elif isinstance(node, dict):
